INSERT INTO maximus_agents.scpi_candidate_metric_evidence
 (scpi_slug,source_period,document_kind,metric,numeric_value,unit,value_basis,
 source_url,source_page,evidence_text,qa_status,independently_reviewed_at,independently_reviewed_by)
SELECT o.slug,'2025-RA','annual_report','valeur_reconstitution_par_part',o.value::numeric,
 'EUR_PER_PART','2025_12_31_NOT_SAME_DATE_AS_2026_T2_PRICE',o.source_url,o.pageno::int,
 o.source_evidence,'qa_pass',now(),
 'QA_2026_10_15_CORUM_ANNUAL_RECONSTITUTION_PAGE_AND_PARTS_ARITHMETIC'
FROM observations o
JOIN maximus_agents.scpi_candidate_pdf_validation d
 ON d.scpi_slug=o.slug AND d.source_period='2025-RA'
 AND d.document_kind='annual_report' AND d.source_url=o.source_url
 AND d.pdf_sha256=o.sha AND d.document_identity_verified
WHERE o.value::numeric>0 AND o.pageno::int BETWEEN 1 AND d.page_count
ON CONFLICT(scpi_slug,source_period,document_kind,metric) DO NOTHING;
